class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(0, 365)
        )

        self.closes = RollingWindow[float](21)
        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.block_entries_on = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnData(self, slice):
        self._liquidate_unexpected_spy_position()

        if self.held_contract is not None and self.Time.date() >= self.held_contract.ID.Date.date():
            self.block_entries_on = self.Time.date()
            if self.Portfolio[self.held_contract].Invested:
                self.Debug(f"Expiration handling: liquidating {self.held_contract}")
                self._submit_exit("expiration")
            return

        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self._is_pre_expiration_time_stop():
            self.Debug(f"Time stop: liquidating {self.held_contract}")
            self._submit_exit("time stop")
            return

        quote = self._find_contract_in_slice(slice, self.held_contract)
        if quote is None:
            return

        if quote.BidPrice > 0 and quote.AskPrice > 0:
            midpoint = (quote.BidPrice + quote.AskPrice) / 2.0
            if self.entry_fill_price is not None and midpoint >= 1.50 * self.entry_fill_price:
                self.Debug(
                    f"Profit target: liquidating {self.held_contract} at midpoint {midpoint:.2f}"
                )
                self._submit_exit("profit target")

    def OnFiveMinuteBar(self, sender, bar):
        if self.Time.date() == self.block_entries_on:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        if self.entry_order_id is not None:
            return

        local_end = bar.EndTime.time()
        if local_end < time(9, 45) or local_end > time(14, 30):
            return

        self.closes.Add(float(bar.Close))
        if self.closes.Count < 21:
            return

        fast_now = sum(self.closes[i] for i in range(5)) / 5.0
        slow_now = sum(self.closes[i] for i in range(20)) / 20.0
        fast_previous = sum(self.closes[i] for i in range(1, 6)) / 5.0
        slow_previous = sum(self.closes[i] for i in range(1, 21)) / 20.0

        if not (fast_previous <= slow_previous and fast_now > slow_now):
            return

        selected = self._select_contract(self.CurrentSlice)
        if selected is None:
            self.Debug(f"Skipped entry at {bar.EndTime}: no qualifying call contract")
            return

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, strike {selected.Strike}, expiry {selected.Expiry.date()}"
        )

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self.spy and self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating SPY")
            self._liquidate_unexpected_spy_position()

        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}")
                self.entry_order_id = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.exit_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def _select_contract(self, slice):
        spot = self.Securities[self.spy].Price
        if spot <= 0:
            return None

        eligible = []
        minimum_expiry = self.Time.date() + timedelta(days=7)

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < minimum_expiry:
                    continue
                eligible.append(contract)

        if not eligible:
            return None

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        minimum_strike = 1.01 * spot

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            return None

        return min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

    def _find_contract_in_slice(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]
        return None

    def _is_pre_expiration_time_stop(self):
        if self.Time.hour != 15 or self.Time.minute != 45:
            return False

        expiry_date = self.held_contract.ID.Date.date()
        prior_trading_day = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(prior_trading_day):
            prior_trading_day -= timedelta(days=1)

        return self.Time.date() == prior_trading_day

    def _submit_exit(self, reason):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, f"Replacing exit for {reason}")

        quantity = -self.Portfolio[self.held_contract].Quantity
        self.exit_order_id = self.MarketOrder(self.held_contract, quantity).OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def _liquidate_unexpected_spy_position(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self.Transactions.GetOpenOrders(self.spy):
            return

        quantity = -self.Portfolio[self.spy].Quantity
        self.MarketOrder(self.spy, quantity)
        self.Debug("Submitted market liquidation for unexpected SPY position")

