from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda u: u.Strikes(-100, 100).Expiration(0, 180))

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_minutes = set()
        self.bucket_close = None

        self.held_contract = None
        self.entry_price = None
        self.contract_expiry = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None
        self.no_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.CheckTimeStop
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.AfterMarketOpen(self.spy, 1),
            self.CheckExpirationProcessing
        )

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()

        if self.held_contract is not None and self.Time.date() >= self.contract_expiry:
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.held_contract].Quantity != 0:
                self.SubmitExit("expiration processing")
            return

        self.CheckProfitTarget(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self.UpdateFiveMinuteBar(spy_bar, data)

    def UpdateFiveMinuteBar(self, bar, data):
        end_time = bar.EndTime
        minute_key = end_time.replace(second=0, microsecond=0)

        minute_remainder = end_time.minute % 5
        if minute_remainder == 0 and end_time.second == 0:
            interval_end = end_time
        else:
            interval_end = end_time + timedelta(minutes=(5 - minute_remainder))
            interval_end = interval_end.replace(second=0, microsecond=0)

        if self.bucket_end is None or interval_end != self.bucket_end:
            self.bucket_end = interval_end
            self.bucket_minutes = set()
            self.bucket_close = None

        self.bucket_minutes.add(minute_key)
        self.bucket_close = bar.Close

        if end_time != self.bucket_end:
            return

        expected_minutes = {
            self.bucket_end - timedelta(minutes=offset)
            for offset in range(1, 6)
        }

        if self.bucket_minutes == expected_minutes:
            self.ProcessCompletedFiveMinuteBar(
                self.bucket_end,
                self.bucket_close,
                data
            )

        self.bucket_end = None
        self.bucket_minutes = set()
        self.bucket_close = None

    def ProcessCompletedFiveMinuteBar(self, end_time, close, data):
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / len(self.fast_closes)
        slow = sum(self.slow_closes) / len(self.slow_closes)

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (end_time.hour == 9 and end_time.minute >= 45) and not (
            end_time.hour > 9 and end_time.hour < 14
        ) and not (end_time.hour == 14 and end_time.minute <= 30):
            return

        self.TryEnter(data)

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.entry_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        spy_bar = data.Bars.get(self.spy)

        if chain is None or spy_bar is None:
            self.Debug("Entry skipped: missing option chain or SPY price")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain)

        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expirations:
            self.Debug("Entry skipped: no expiration at least seven days away")
            return

        selected_expiry = valid_expirations[0]
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call contract")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.contract_expiry = selected.Expiry.date()
        self.entry_price = None

        self.Debug(
            f"Entry submitted: {selected.Symbol} exp {selected.Expiry.date()} "
            f"strike {selected.Strike}"
        )

    def CheckProfitTarget(self, data):
        if self.held_contract is None:
            return

        if self.entry_price is None:
            return

        if self.Portfolio[self.held_contract].Quantity <= 0:
            return

        if self.exit_order_id is not None:
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def CheckTimeStop(self):
        if self.held_contract is None or self.contract_expiry is None:
            return

        if self.Portfolio[self.held_contract].Quantity <= 0:
            return

        previous_trading_day = self.Securities[
            self.spy
        ].Exchange.Hours.GetPreviousTradingDay(
            datetime.combine(self.contract_expiry, datetime.min.time())
        ).date()

        if self.Time.date() == previous_trading_day:
            self.SubmitExit("15:45 pre-expiration time stop")

    def CheckExpirationProcessing(self):
        if self.held_contract is None or self.contract_expiry is None:
            return

        if self.Time.date() >= self.contract_expiry:
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.held_contract].Quantity != 0:
                self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, "Replacing exit order")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self.held_contract}")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity == 0:
            return

        if self.equity_liquidation_order_id is None:
            ticket = self.Liquidate(self.spy, "Unexpected option exercise or assignment")
            self.equity_liquidation_order_id = ticket.OrderId
            self.Debug("Unexpected SPY exercise/assignment position: liquidation submitted")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(f"Entry canceled/invalid: {self.held_contract}")
                self.entry_order_id = None
                self.held_contract = None
                self.entry_price = None
                self.contract_expiry = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {self.held_contract} at {order_event.FillPrice}"
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_price = None
                self.contract_expiry = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

        if order_event.OrderId == self.equity_liquidation_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.equity_liquidation_order_id = None

